def iki_toplam(sayilar, hedef):
    gorulen = {}
    for i, s in enumerate(sayilar):
        if hedef - s in gorulen:
            return (gorulen[hedef - s], i)
        gorulen[s] = i
    return None

print(iki_toplam([2, 7, 11, 15], 9))
print(iki_toplam([3, 3], 6))
print(iki_toplam([1, 2], 10))

def indirim_uygula(tutar, yuzde):
    if yuzde < 0 or yuzde > 100:
        raise ValueError("yuzde 0-100 arasinda olmali")
    return tutar - tutar * yuzde / 100

def kontrol(ad, beklenen, gercek):
    print(ad, "GECTI" if beklenen == gercek else "BASARISIZ")

kontrol("yuzde_10", 180.0, indirim_uygula(200.0, 10))
kontrol("yuzde_0", 200.0, indirim_uygula(200.0, 0))
try:
    indirim_uygula(200.0, -5)
    print("negatif BASARISIZ")
except ValueError:
    print("negatif GECTI")
